import React, { useEffect, useState } from 'react';
import Leaflet from 'leaflet';
import 'leaflet/dist/leaflet.css';
import 'bootstrap/dist/css/bootstrap.min.css';

function Airport() {
  const [origin, setOrigin] = useState('');
  const [destination, setDestination] = useState('');
  const [routeSteps, setRouteSteps] = useState([]);
  const [totalDistance, setTotalDistance] = useState(0);

  useEffect(() => {
    // Initialize map
    const map = Leaflet.map('map').setView([51.505, -0.09], 13);
    Leaflet.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      attribution: '&copy; <a href="https://www.openstreetmap.org/">OpenStreetMap</a>',
      subdomains: ['a', 'b', 'c'],
    }).addTo(map);
  }, []);

  return (
    <div>
      <nav className="navbar navbar-expand-lg navbar-light bg-light">
        <a className="navbar-brand" href="/">
          Air Traffic Control
        </a>
        <div className="collapse navbar-collapse">
          <ul className="navbar-nav mr-auto">
            <li className="nav-item">
              <a className="nav-link" href="/">
                Home
              </a>
            </li>
            <li className="nav-item">
              <a className="nav-link" href="/airports">
                Airports
              </a>
            </li>
            <li className="nav-item">
              <a className="nav-link" href="/planes">
                Planes
              </a>
            </li>
            <li className="nav-item">
              <a className="nav-link" href="/route">
                Find Shortest Route
              </a>
            </li>
          </ul>
        </div>
      </nav>

      <div className="container mt-4">
        <h1>
          Shortest Route from {origin} to {destination}
        </h1>

        {routeSteps.length > 0 && (
          <div>
            <p>
              Total Distance: {totalDistance} km
            </p>

            <ol>
              {routeSteps.map((step, index) => (
                <li key={index}>{step}</li>
              ))}
            </ol>

            {/* Map Container */}
            <div id="map"></div>
          </div>
        )}

        {routeSteps.length === 0 && (
          <div className="space">
            <p>No route found. Please check the airport codes and try again.</p>
          </div>
        )}

        <a className="btn btn-primary" href="/route">
          Find Another Route
        </a>
      </div>
    </div>
  );
}

export default Airport;
